import React, { useState, useEffect } from 'react';
import { getStore1CategoryStocks } from '../services/stockService';

const Dashboard = () => {
    const [categoryStocks, setCategoryStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchCategoryStocks = async () => {
            try {
                const response = await getStore1CategoryStocks();
                if (response && response.categoryStocks) {
                    setCategoryStocks(response.categoryStocks);
                    setError(null);
                }
            } catch (err) {
                setError('Kategori stokları yüklenirken bir hata oluştu');
            } finally {
                setLoading(false);
            }
        };

        fetchCategoryStocks();
    }, []);

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Dashboard</h1>
            
            {/* Stok Özeti Kartları */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                <div className="bg-white rounded-lg shadow-md p-6">
                    <h3 className="text-lg font-semibold text-gray-800 mb-2">Toplam Kategori</h3>
                    <p className="text-3xl font-bold text-blue-600">{categoryStocks.length}</p>
                </div>
                <div className="bg-white rounded-lg shadow-md p-6">
                    <h3 className="text-lg font-semibold text-gray-800 mb-2">Toplam Stok</h3>
                    <p className="text-3xl font-bold text-green-600">
                        {categoryStocks.reduce((total, stock) => total + stock.totalQuantity, 0)}
                    </p>
                </div>
            </div>

            {/* Kategori Stok Tablosu */}
            <div className="bg-white rounded-lg shadow-md overflow-hidden">
                <div className="p-6">
                    <h2 className="text-xl font-bold mb-4">Kategori Bazlı Stok Durumu</h2>
                    {loading ? (
                        <div className="flex justify-center items-center h-32">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500"></div>
                        </div>
                    ) : error ? (
                        <div className="text-red-500 text-center py-4">{error}</div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Kategori
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Stok Miktarı
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                            Stok Durumu
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {categoryStocks.map((stock, index) => (
                                        <tr key={index} className={index % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                                {stock.category}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                                {stock.totalQuantity}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                                                    stock.totalQuantity > 50 ? 'bg-green-100 text-green-800' :
                                                    stock.totalQuantity > 20 ? 'bg-yellow-100 text-yellow-800' :
                                                    'bg-red-100 text-red-800'
                                                }`}>
                                                    {stock.totalQuantity > 50 ? 'Yeterli Stok' :
                                                     stock.totalQuantity > 20 ? 'Orta Stok' :
                                                     'Düşük Stok'}
                                                </span>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
